#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstdio>
using namespace std;

using i64 = long long;

const int INF = 0x7f7f7f7f;
const int MAX_NODES = 5010000;
const int MOD = 1000000007;

struct Edge {
    int to;
    int capacity;
    int cost;
    int next;
};

vector<Edge> graph;
vector<int> adjHead;

void link(int u, int v, int cap, int cost) {
    graph.push_back({v, cap, cost, adjHead[u]});
    adjHead[u] = static_cast<int>(graph.size()) - 1;
    graph.push_back({u, 0, -cost, adjHead[v]});
    adjHead[v] = static_cast<int>(graph.size()) - 1;
}

void input(int &x) {
    x = 0;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') break;
        c = getchar();
    }
    bool neg = false;
    if (c == '-') {
        neg = true;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

void outputNumber(int x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    if (x > 9) outputNumber(x / 10);
    putchar(x % 10 + '0');
}

void outputLine(int x) {
    outputNumber(x);
    putchar('\n');
}

int sourceNode, sinkNode;
vector<int> shortestDist, bottleneckFlow, predecessorNode, predecessorEdge;
vector<bool> inQueue;

bool spfaShortestPath() {
    fill(shortestDist.begin(), shortestDist.end(), INF);
    fill(bottleneckFlow.begin(), bottleneckFlow.end(), 0);
    fill(predecessorNode.begin(), predecessorNode.end(), -1);
    fill(predecessorEdge.begin(), predecessorEdge.end(), -1);
    fill(inQueue.begin(), inQueue.end(), false);

    queue<int> q;
    shortestDist[sourceNode] = 0;
    bottleneckFlow[sourceNode] = INF;
    q.push(sourceNode);
    inQueue[sourceNode] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = false;

        for (int idx = adjHead[u]; idx != -1; idx = graph[idx].next) {
            int v = graph[idx].to;
            int cap = graph[idx].capacity;
            int cost = graph[idx].cost;

            if (cap > 0 && shortestDist[v] > shortestDist[u] + cost) {
                shortestDist[v] = shortestDist[u] + cost;
                bottleneckFlow[v] = min(bottleneckFlow[u], cap);
                predecessorNode[v] = u;
                predecessorEdge[v] = idx;
                if (!inQueue[v]) {
                    q.push(v);
                    inQueue[v] = true;
                }
            }
        }
    }

    return predecessorNode[sinkNode] != -1;
}

int totalFlow, minimumCost;

void minCostMaximumFlow() {
    while (spfaShortestPath()) {
        int flowPush = bottleneckFlow[sinkNode];
        totalFlow += flowPush;
        minimumCost += flowPush * shortestDist[sinkNode];

        int current = sinkNode;
        while (current != sourceNode) {
            graph[predecessorEdge[current]].capacity -= flowPush;
            graph[predecessorEdge[current] ^ 1].capacity += flowPush;
            current = predecessorNode[current];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    input(n); input(m); input(k); input(c); input(d);

    int B = max(n, k);
    sourceNode = n * (2 * B + 1) + 1;
    sinkNode = sourceNode + 1;

    shortestDist.resize(sinkNode + 1);
    bottleneckFlow.resize(sinkNode + 1);
    predecessorNode.resize(sinkNode + 1);
    predecessorEdge.resize(sinkNode + 1);
    inQueue.resize(sinkNode + 1);
    adjHead.assign(sinkNode + 1, -1);

    for (int i = 0; i < k; i++) {
        int x;
        input(x);
        link(sourceNode, x, 1, 0);
    }

    link(n * (2 * B) + 1, sinkNode, INF, 0);

    for (int layer = 0; layer < 2 * B; layer++) {
        link(layer * n + 1, (layer + 1) * n + 1, INF, 0);
        for (int i = 2; i <= n; i++) {
            link(layer * n + i, (layer + 1) * n + i, INF, c);
        }
    }

    for (int i = 0; i < m; i++) {
        int x, y;
        input(x); input(y);
        for (int layer = 0; layer < 2 * B; layer++) {
            for (int j = 1; j <= k; j++) {
                int cost = d * (2 * j - 1) + c;
                link(layer * n + x, (layer + 1) * n + y, 1, cost);
                link(layer * n + y, (layer + 1) * n + x, 1, cost);
            }
        }
    }

    minCostMaximumFlow();
    outputLine(minimumCost);

    return 0;
}
